package com.example.graphql.pagination;

import graphql.relay.Connection;
import graphql.relay.ConnectionCursor;
import graphql.relay.DefaultConnection;
import graphql.relay.DefaultEdge;
import graphql.relay.DefaultPageInfo;
import graphql.relay.Edge;
import graphql.relay.PageInfo;
import graphql.schema.DataFetchingEnvironment;
import org.springframework.stereotype.Component;
import java.util.Base64;
import java.util.List;
import java.util.stream.Collectors;

@Component
public class UserConnectionResolver {

    public Connection<User> fetchUsers(DataFetchingEnvironment env) {
        Integer first = env.getArgument("first");
        String after = env.getArgument("after");

        long decodedOffset = decodeCursor(after);
        List<User> users = userRepository.fetchPage(decodedOffset, first + 1);

        boolean hasNextPage = users.size() > first;
        if (hasNextPage) {
            users = users.subList(0, first);
        }

        List<Edge<User>> edges = users.stream().map(user -> 
            (Edge<User>) new DefaultEdge<>(user, encodeCursor(user.getId()))
        ).collect(Collectors.toList());

        ConnectionCursor startCursor = edges.isEmpty() ? null : edges.get(0).getCursor();
        ConnectionCursor endCursor = edges.isEmpty() ? null : edges.get(edges.size() - 1).getCursor();

        PageInfo pageInfo = new DefaultPageInfo(startCursor, endCursor, false, hasNextPage);
        return new DefaultConnection<>(edges, pageInfo);
    }

    private String encodeCursor(Long id) {
        return Base64.getEncoder().encodeToString(("cursor:" + id).getBytes());
    }

    private long decodeCursor(String cursor) {
        if (cursor == null) return 0L;
        String decoded = new String(Base64.getDecoder().decode(cursor));
        return Long.parseLong(decoded.split(":")[1]);
    }
}
